import React, { useEffect, useState } from "react";
import AnimationRevealPage from "helpers/AnimationRevealPage";
import tw from "twin.macro";

const Container = tw.div`min-h-screen flex flex-col items-center justify-center p-8`;
const Card = tw.div`w-full max-w-xl bg-white shadow rounded p-6`;
const Title = tw.h1`text-2xl font-bold mb-4`;
const Para = tw.p`mb-2`;
const Input = tw.input`w-full px-3 py-2 border rounded`;
const Button = tw.button`mt-3 px-4 py-2 bg-primary-500 text-white rounded`;

export default function Dashboard() {
  const [user, setUser] = useState(null);
  const [referralUrl, setReferralUrl] = useState("");

  useEffect(() => {
    const u = localStorage.getItem('user');
    if (u) {
      const parsed = JSON.parse(u);
      setUser(parsed);
      const origin = window.location.origin;
      setReferralUrl(`${origin}/api/ref/${parsed.referralCode}`);
    }
  }, []);

  if (!user) return (
    <AnimationRevealPage>
      <Container>
        <Card>
          <Title>Please log in</Title>
          <Para><a href="/login">Go to Login</a></Para>
        </Card>
      </Container>
    </AnimationRevealPage>
  );

  const copy = async () => {
    await navigator.clipboard.writeText(referralUrl);
    alert('Referral link copied');
  };

  return (
    <AnimationRevealPage>
      <Container>
        <Card>
          <Title>Welcome, {user.name}</Title>
          <Para>Your referral link:</Para>
          <Input readOnly value={referralUrl} />
          <Button onClick={copy}>Copy</Button>
          <Para tw="mt-4">Current referrals: <b>{user.referrals || 0}</b> (refresh after successful registrations)</Para>
          <Para tw="mt-2"><a href="/leaderboard">View Leaderboard</a></Para>
          <Para tw="mt-2">Event registration page: <a href="https://tikkl.com/bgm/c/bgm26-hyd" target="_blank" rel="noreferrer">Tikkl BGM 2026 Hyderabad</a></Para>
        </Card>
      </Container>
    </AnimationRevealPage>
  );
}
